        </TableCell>
        <TableCell sx={{ width: "45%" }}>
          {formatAddress({
            addressLine1: pharmacy.addressLine1,
            addressLine2: pharmacy.addressLine2,
            city: pharmacy.city,
            state: pharmacy.state,
            zipCode: pharmacy.zip.slice(0, 5),
          })}
        </TableCell>
        <TableCell sx={{ width: "10%" }}>
          {renderActionCell(pharmacy)}
        </TableCell>
      </TableRow>
    ))}
  </>
)}

{isLoading ? (
  <CircularProgress thickness={5} sx={spinnerStyles} />
) : (
  <Table size="small" sx={{ mb: 2 }}>
    <TableHead>
      <TableRow>
        {TABLE_HEADERS.map((header) => (
          <TableCell key={header.id}>{header.label}</TableCell>
        ))}
        <TableCell />
      </TableRow>
    </TableHead>
    <TableBody sx={{ minHeight: "200px !important" }}>
      {pharmacies.length === 0 ? (
        <TableRow>
          <TableCell colSpan={3}>
            <Typography>{NO_PHARMACY_FOUND_MESSAGE}</Typography>
          </TableCell>
        </TableRow>
      ) : (
        <>
          {pharmacies.map((pharmacy) => (
            <TableRow key={pharmacy.pharmacyId}>
              <TableCell sx={{ width: "45%" }}>
                {pharmacy.storeName}
              </TableCell>
              <TableCell sx={{ width: "45%" }}>
                {formatAddress({
                  addressLine1: pharmacy.addressLine1,
                  addressLine2: pharmacy.addressLine2,
                  city: pharmacy.city,
                  state: pharmacy.state,
                  zipCode: pharmacy.zip.slice(0, 5),
                })}
              </TableCell>
              <TableCell sx={{ width: "10%" }}>
                {renderActionCell(pharmacy)}
              </TableCell>
            </TableRow>
          ))}
        </>
      )}
    </TableBody>
  </Table>
)}

{rows.map((row) => (
  <TableRow key={getRowKey(row)}>
    {columns.map((column, index) => (
      <TableCell
        key={column.header}
        component={index === 0 ? "th" : "td"}
        scope={index === 0 ? "row" : undefined}
      >
        {column.render(row)}
      </TableCell>
    ))}
  </TableRow>
))}
